    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        INF = 10 ** 9

        def can(limit: int) -> bool:
            if limit >= n:
                return True

            dp = [[INF] * (limit + 1) for _ in range(2)]
            first = 0 if s[0] == '0' else 1
            dp[first][1] = 0
            dp[1 - first][1] = 1

            for ch in s[1:]:
                orig = 0 if ch == '0' else 1
                ndp = [[INF] * (limit + 1) for _ in range(2)]

                for last in (0, 1):
                    for run in range(1, limit + 1):
                        cur = dp[last][run]
                        if cur == INF:
                            continue

                        if run < limit:
                            add = 1 if orig != last else 0
                            nxt = cur + add
                            if nxt < ndp[last][run + 1]:
                                ndp[last][run + 1] = nxt

                        other = 1 - last
                        add = 1 if orig != other else 0
                        nxt = cur + add
                        if nxt < ndp[other][1]:
                            ndp[other][1] = nxt

                dp = ndp

            best = INF
            for last in (0, 1):
                for run in range(1, limit + 1):
                    best = min(best, dp[last][run])

            return best <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

