from functools import lru_cache
from collections import deque

class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        n = len(positions)
        coords = [(kx, ky)] + [(x, y) for x, y in positions]
        m = n + 1
        dist = [[0] * m for _ in range(m)]
        dirs = [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]

        for i, (x, y) in enumerate(coords):
            d = [[-1] * 50 for _ in range(50)]
            q = deque([(x, y)])
            d[x][y] = 0
            while q:
                cx, cy = q.popleft()
                for dx, dy in dirs:
                    nx, ny = cx + dx, cy + dy
                    if 0 <= nx < 50 and 0 <= ny < 50 and d[nx][ny] == -1:
                        d[nx][ny] = d[cx][cy] + 1
                        q.append((nx, ny))
            for j, (x2, y2) in enumerate(coords):
                dist[i][j] = d[x2][y2]

        full_mask = (1 << n) - 1

        @lru_cache(None)
        def dp(mask: int, src: int) -> int:
            if mask == 0:
                return 0

            captured = n - bin(mask).count("1")
            best = None
            rem = mask

            while rem:
                lsb = rem & -rem
                i = lsb.bit_length() - 1
                nxt_src = 1 + i

                val = dist[src][nxt_src] + dp(mask ^ lsb, nxt_src)

                if best is None:
                    best = val
                elif captured % 2 == 0:
                    best = max(best, val)
                else:
                    best = min(best, val)

                rem ^= lsb

            return best

        return dp(full_mask, 0)
