class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        bits = [0] * (n + 1)
        for i in range(1, n + 1):
            bits[i] = 1 << (i - 1)

        ans = 0

        for left in range(n):
            mask = 0
            imbalance = 0

            for right in range(left, n):
                v = nums[right]
                idx = v - 1
                bit = bits[v]

