                        if lower_mask:
                            pred_idx = lower_mask.bit_length() - 1

                    succ_idx = -1
                    shifted = mask >> (idx + 1)
                    if shifted:
                        lowbit = shifted & -shifted
                        succ_idx = idx + 1 + (lowbit.bit_length() - 1)

