from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        size = 1
        while size < n:
            size <<= 1

        tree = [-1] * (2 * size)
        for i in range(n):
            tree[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        def update(idx: int, val: int) -> None:
            i = idx + size
            tree[i] = val
            i //= 2
            while i:
                tree[i] = max(tree[2 * i], tree[2 * i + 1])
                i //= 2

        def find_first(node: int, l: int, r: int, fruit: int) -> int:
            if tree[node] < fruit:
                return -1
            if l == r:
                return l
            mid = (l + r) // 2
            left_child = node * 2
            if tree[left_child] >= fruit:
                return find_first(left_child, l, mid, fruit)
            else:
                return find_first(left_child + 1, mid + 1, r, fruit)

        unplaced = 0
        for f in fruits:
            idx = find_first(1, 0, size - 1, f)
            if idx == -1 or idx >= n:
                unplaced += 1
            else:
                update(idx, -1)

        return unplaced
