    # Stirling numbers of the second kind S2[n][k]
    S2 = [[0] * (K + 1) for _ in range(K + 1)]
    S2[0][0] = 1
    for n in range(1, K + 1):
        for k in range(1, n + 1):
            S2[n][k] = (S2[n - 1][k - 1] + k * S2[n - 1][k]) % MOD

    # signed Stirling numbers of the first kind s[n][k] for falling factorial (x)_n
    s = [[0] * (K + 1) for _ in range(K + 1)]
    s[0][0] = 1
    for n in range(1, K + 1):
        for k in range(1, n + 1):
            s[n][k] = (s[n - 1][k - 1] - (n - 1) * s[n - 1][k]) % MOD

    # F[p] = sum over all subarrays of (sum)^p
    F = [0] * (K + 1)
    F[0] = (N * (N + 1) // 2) % MOD

    S_pow = [0] * (K + 1)
