from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_upto(n: int) -> int:
            if n <= 0:
                return 0

            digits = [int(c) for c in str(n)]
            L = len(digits)

            @lru_cache(None)
            def dp(pos: int, tight: bool, started: bool, digit_sum: int, prod: int) -> int:
                if pos == L:
                    if not started:
                        return 0
                    return 1 if prod % digit_sum == 0 else 0

                limit = digits[pos] if tight else 9
                ans = 0

                for d in range(limit + 1):
                    next_tight = tight and (d == digits[pos])

                    if not started and d == 0:
                        ans += dp(pos + 1, next_tight, False, 0, 1)
                    else:
                        next_sum = digit_sum + d
                        next_prod = d if not started else prod * d
                        ans += dp(pos + 1, next_tight, True, next_sum, next_prod)

                return ans

            return dp(0, True, False, 0, 1)

        return count_upto(r) - count_upto(l - 1)
